// План specs/multi-business.md 1.1–1.2 (кейсы MB-01, MB-02). Владелец (admin), бизнесы «test» и «Onsite Locksmith». @prod-safe:
// только просмотр — ничего не создаётся, JobDetail только открывается. В конце теста всегда возвращается бизнес «test».
import { test, expect } from '../../fixtures';
import {
  DATA, ONSITE_COMPANY, TEST_COMPANY,
  companyOption, companyOptions, expectSelected, firstJobCode, jobRow, openClients, openJobs, openSwitcher,
  restoreTest, search, startInTest, switchTo,
} from './business-helpers';

test.describe('Multi-business: owner switcher isolation (#04d339)', () => {
  test('Owner: switcher lists exactly test and Onsite Locksmith; QA-B2 client is visible only in Onsite #04d339 @desktop @prod-safe', async ({ asUser }) => {
    const owner = await asUser('admin');
    await startInTest(owner);
    try {
      await owner.goto('/dashboard');
      await expectSelected(owner, TEST_COMPANY.name);

      // В переключателе ровно 2 бизнеса (источник: DoD «חשבון-על מכיל כמה עסקים»).
      await openSwitcher(owner);
      await expect(companyOption(owner, ONSITE_COMPANY.name)).toBeVisible();
      await expect(companyOptions(owner)).toHaveCount(2);
      await owner.keyboard.press('Escape');

      // test: «QA-quota client» находится поиском (якорь), поиск «QA-B2» — якорь пропал, клиента Onsite нет.
      const main = owner.locator('main');
      await openClients(owner);
      await search(owner, 'QA-quota');
      await expect(main.getByText(DATA.testClient).first()).toBeVisible();
      await search(owner, DATA.onsiteSearch);
      await expect(main.getByText(DATA.testClient)).toHaveCount(0);
      await expect(main.getByText(DATA.onsiteClient)).toHaveCount(0);

      // Onsite: клиент QA-B2 есть, клиента из test нет (источник: DoD «מתג הקשר מציג רק נתוני העסק הנבחר»).
      await switchTo(owner, ONSITE_COMPANY.name);
      await openClients(owner);
      await search(owner, DATA.onsiteSearch);
      await expect(main.getByText(DATA.onsiteClient).first()).toBeVisible();
      await search(owner, 'QA-quota');
      await expect(main.getByText(DATA.onsiteClient)).toHaveCount(0);
      await expect(main.getByText(DATA.testClient)).toHaveCount(0);
    } finally {
      await restoreTest(owner);
    }
  });

  test('Owner: JOB-1036 (QA-B2 job) is listed only in Onsite, JOB-0094 opens in test #04d339 @desktop @prod-safe', async ({ asUser }) => {
    const owner = await asUser('admin');
    await startInTest(owner);
    try {
      // test: работа из test открывается (только просмотр, в JobDetail ничего не трогаем).
      await owner.goto(`/JobDetail?id=${DATA.testJob.id}`);
      await expect(owner.locator('main')).toContainText(new RegExp(`JOB-\\s*${DATA.testJob.code.slice(4)}`), { timeout: 30_000 });
      await expectSelected(owner, TEST_COMPANY.name);

      // test, Jobs: поиск «QA-B2» — JOB-1036 нет; якорная работа пропала → фильтр применился.
      await openJobs(owner);
      const anchor = await firstJobCode(owner, DATA.onsiteJob);
      await search(owner, DATA.onsiteSearch);
      await expect(jobRow(owner, anchor)).toHaveCount(0);
      await expect(jobRow(owner, DATA.onsiteJob)).toHaveCount(0);

      // Onsite, Jobs (вкладка по умолчанию — Submitted): JOB-1036 клиента QA-B2 есть, JOB-0094 нет.
      // не проверено на сайте при записи: в какой вкладке статуса JOB-1036 и ищет ли поиск по имени клиента.
      await switchTo(owner, ONSITE_COMPANY.name);
      await openJobs(owner);
      await expect(jobRow(owner, DATA.testJob.code)).toHaveCount(0);
      await search(owner, DATA.onsiteSearch);
      await expect(jobRow(owner, DATA.onsiteJob)).toBeVisible();
      await expect(jobRow(owner, DATA.onsiteJob)).toContainText(DATA.onsiteClient.replace(/ client$/, ''));
    } finally {
      await restoreTest(owner);
    }
  });
});
